func TestUnderstandReplay_AllEvents(t *testing.T) {
	dir := t.TempDir()
	testutil.InitRepo(t, dir)
	seedReplayCache(t, dir)
	t.Chdir(dir)
	paths.ClearWorktreeRootCache()

	var buf bytes.Buffer
	if err := runUnderstandReplay(context.Background(), &buf, replayOptions{JSONOut: true}); err != nil {
		t.Fatalf("runUnderstandReplay: %v", err)
	}
	var got replayReport
	if err := json.Unmarshal(buf.Bytes(), &got); err != nil {
		t.Fatalf("decode: %v\nraw=%s", err, buf.String())
	}
	if len(got.Events) != 3 {
		t.Errorf("Events=%d; want 3", len(got.Events))
	}
	// Events should be sorted by At ascending.
	if got.Events[0].CheckpointID != "aaaa" || got.Events[2].CheckpointID != "cccc" {
		t.Errorf("event order wrong: %+v", got.Events)
	}
